{
  "definition_simple": "Supported, confirmed, or maintained a decision, law, or principle against challenge.",
  "definition_standard": "Affirmed or defended the validity of a prior legal ruling, custom, or standard against objection or appeal.",
  "pos": "verb",
  "semantic_class": "action",
  "sentences": [
    {
      "text": "The judge upheld the original rule.",
      "tier": "T1"
    },
    {
      "text": "The school board upheld the principal's decision.",
      "tier": "T2"
    },
    {
      "text": "She upheld her family's long tradition of community service.",
      "tier": "T3"
    },
    {
      "text": "The committee upheld the ban on single-use plastics.",
      "tier": "T3"
    },
    {
      "text": "The appeals court upheld the conviction after reviewing the new evidence.",
      "tier": "T4"
    },
    {
      "text": "Throughout the crisis, the officers upheld their oath of duty.",
      "tier": "T4"
    },
    {
      "text": "The state supreme court unanimously upheld the lower court's ruling on constitutional grounds.",
      "tier": "T5"
    },
    {
      "text": "Despite intense public pressure, the regulatory agency upheld the environmental standards.",
      "tier": "T5"
    },
    {
      "text": "The international tribunal upheld the maritime treaty, citing decades of customary law.",
      "tier": "T6"
    },
    {
      "text": "In an unprecedented decree, the constitutional council upheld the validity of the contested election.",
      "tier": "T6"
    }
  ],
  "morphological_forms": [
    {
      "form": "uphold",
      "label": "base_form"
    },
    {
      "form": "upholding",
      "label": "present_participle"
    }
  ],
  "morphology_wrong_forms": {
    "uphold": [
      {
        "form": "uphelded",
        "explanation": "Incorrectly applies regular past-tense '-ed' inflection to an already irregular past-tense stem."
      },
      {
        "form": "upholden",
        "explanation": "Archaically attempts to form a strong past participle by analogy with 'beholden' or 'holden'."
      },
      {
        "form": "uphelding",
        "explanation": "Erroneously attaches the progressive participle suffix '-ing' to the past-tense stem instead of the base stem."
      }
    ],
    "upholding": [
      {
        "form": "upholdening",
        "explanation": "Double-inflects the participle by stacking an archaic participle ending '-en' before the suffix '-ing'."
      },
      {
        "form": "upholdinged",
        "explanation": "Combines continuous and past markers into a single illegitimate suffix cluster."
      },
      {
        "form": "upholdin",
        "explanation": "Truncates the velar nasal coda into an informal phonetic spelling unsuited for standard morphology."
      }
    ]
  },
  "l1_audio_confusables": [
    {
      "word": "withheld",
      "explanation": "Shares the exact rhyme and past-tense participle ending /-hɛld/ but begins with a different prefix /wɪð-/ rather than /ʌp-/ and means retained or refused to yield."
    },
    {
      "word": "unheld",
      "explanation": "Differs only by the prefix-coda nasal /n/ versus bilabial stop /p/, referring to something not grasped or retained."
    },
    {
      "word": "upheaved",
      "explanation": "Shares the initial /ʌp-/ prefix and similar cadence, but ends with /-hiːvd/ and refers to forceful physical displacement rather than legal affirmation."
    }
  ],
  "primary_collocate": "ruling",
  "collocation_distractors": [
    {
      "word": "punishment",
      "explanation": "Courts administer, mitigate, or suspend a punishment, but they formally uphold a ruling, decision, or conviction rather than the punishment itself."
    },
    {
      "word": "opinion",
      "explanation": "Judges deliver, issue, or draft an opinion, but they do not use 'uphold' to describe endorsing another justice's written commentary."
    },
    {
      "word": "testimony",
      "explanation": "Witness testimony is credited, corroborated, or impeached, whereas 'uphold' requires an institutional or legal determination as its target."
    }
  ],
  "collocation_wrong_collocate": "lawsuit",
  "cloze_distractors": [
    {
      "word": "overturned",
      "explanation": "Presents an exact antonym of 'upheld', representing the reversal rather than the affirmation of the lower court's finding."
    },
    {
      "word": "uplifted",
      "explanation": "Confuses the abstract legal sense of 'uphold' with a literal or emotional elevation inappropriate for judicial register."
    },
    {
      "word": "entertained",
      "explanation": "Means to consider or listen to an argument, which fails to convey the finality of officially validating the conviction."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "The laborer upheld the ceiling joist with a wooden post while repairs were underway.",
      "reason": "Uses 'upheld' for physical, structural propping; the physical action requires 'held up' or 'supported', as 'upheld' is restricted to abstract, moral, or legal maintenance."
    },
    {
      "sentence": "The jury upheld the defendant guilty after reviewing the surveillance footage.",
      "reason": "Violates argument structure by treating 'upheld' as a complex-transitive verb taking an object and an adjective complement; English requires 'found the defendant guilty'."
    },
    {
      "sentence": "She upheld to complete the project before the end of the fiscal quarter.",
      "reason": "Improperly complements 'upheld' with a to-infinitive clause; the verb is strictly transitive and must govern a direct noun phrase representing a standard, duty, or ruling."
    }
  ],
  "spot_incorrect": {
    "sentence": "The Supreme Court was upheld the statute after hearing oral arguments from both state attorneys.",
    "error_description": "The active transitive clause incorrectly introduces the auxiliary 'was', mistakenly converting an active agent into a passive construct while still retaining a direct object.",
    "corrected": "The Supreme Court upheld the statute after hearing oral arguments from both state attorneys."
  },
  "word_family_forms": [
    "upholder"
  ],
  "word_family_fake_forms": [
    "upholdment",
    "upholdative",
    "upholdation"
  ],
